    /**
     * Resets the cached bounds, by iterating over the entire dataset to find
     * the current bounds.
     */
    private void updateBounds() {
        this.minimumRangeValue = Double.NaN;
        this.minimumRangeValueRow = -1;
        this.minimumRangeValueColumn = -1;
        this.maximumRangeValue = Double.NaN;
        this.maximumRangeValueRow = -1;
        this.maximumRangeValueColumn = -1;
        int rowCount = this.data.getRowCount();
        int colCount = this.data.getColumnCount();
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                BoxAndWhiskerItem item = (BoxAndWhiskerItem) this.data.getObject(r, c);
                if (item != null) {
                    double minval = Double.NaN;
                    if (item.getMinOutlier() != null) {
                        minval = item.getMinOutlier().doubleValue();
                    }
                    double maxval = Double.NaN;
                    if (item.getMaxOutlier() != null) {
                        maxval = item.getMaxOutlier().doubleValue();
                    }

                    if (Double.isNaN(this.maximumRangeValue)) {
                        this.maximumRangeValue = maxval;
                        this.maximumRangeValueRow = r;
                        this.maximumRangeValueColumn = c;
                    }
                    else if (maxval > this.maximumRangeValue) {
                        this.maximumRangeValue = maxval;
                        this.maximumRangeValueRow = r;
                        this.maximumRangeValueColumn = c;
                    }

                    if (Double.isNaN(this.minimumRangeValue)) {
                        this.minimumRangeValue = minval;
                        this.minimumRangeValueRow = r;
                        this.minimumRangeValueColumn = c;
                    }
                    else if (minval < this.minimumRangeValue) {
                        this.minimumRangeValue = minval;
                        this.minimumRangeValueRow = r;
                        this.minimumRangeValueColumn = c;
                    }
                }
            }
        }
        if (Double.isNaN(this.minimumRangeValue)) {
            this.rangeBounds = null;
        }
        else {
            this.rangeBounds = new Range(this.minimumRangeValue, this.maximumRangeValue);
        }
    }

    /**
     * Tests this dataset for equality with an arbitrary object.
     * 
     * @param obj  the object to test against (<code>null</code> permitted).
     * 
     * @return A boolean.
     */
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;   
        }
        if (obj instanceof DefaultBoxAndWhiskerCategoryDataset) {
            DefaultBoxAndWhiskerCategoryDataset dataset 
                    = (DefaultBoxAndWhiskerCategoryDataset) obj;
            return ObjectUtilities.equal(this.data, dataset.data);
        }
        return false;
    }

    /**
