    /**
     * The URL for the label (<code>null</code> is permitted).
     * 
     * @since 1.2.0.
     */
    private String labelURL;

    /** A flag that controls whether or not the axis line is visible. */
    private boolean axisLineVisible;

    /** The stroke used for the axis line. */
