  private boolean hasExceptionHandler(Node cfgNode) {
    GraphNode<Node, Branch> n = getCfg().getNode(cfgNode);
    if (n != null) {
      for (DiGraphEdge<Node, Branch> edge : n.getOutEdges()) {
        if (edge.getValue() == Branch.ON_EX) {
          return true;
