    if (implicitPrototype != null) {
      Property prop = implicitPrototype.getSlot(name);
      if (prop != null) {
        return prop;
      }
    }
    for (ObjectType interfaceType : getCtorExtendedInterfaces()) {
      Property prop = interfaceType.getSlot(name);
      if (prop != null) {
        return prop;
      }
    }
    return null;
